#!/usr/bin/env python3
"""Build a self-contained viewer for pairwise disagreements and order effects."""

from __future__ import annotations

import json
from pathlib import Path

EXPERIMENT_DIR = Path(__file__).resolve().parents[1]
RESULTS_DIR = EXPERIMENT_DIR / "results" / "full"
OUTPUT = RESULTS_DIR / "qualitative_review.html"


def main() -> None:
    analysis = json.loads((RESULTS_DIR / "analysis.json").read_text(encoding="utf-8"))
    comparisons = json.loads(
        (RESULTS_DIR / "scenario_comparison.json").read_text(encoding="utf-8")
    )
    payload = json.dumps(
        {"analysis": analysis, "comparisons": comparisons}, ensure_ascii=False
    ).replace("</", "<\\/")
    OUTPUT.write_text(TEMPLATE.replace("__DATA__", payload), encoding="utf-8")
    print(f"Wrote {OUTPUT} ({OUTPUT.stat().st_size:,} bytes)")


TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>HERON · Pairwise judge review</title>
  <style>
    :root { --ink:#18221d;--muted:#69736d;--paper:#f3efe6;--panel:#fffdf8;--line:#d9d2c4;--green:#175c45;--green2:#dcebe2;--red:#963c35;--red2:#f3ded9;--blue:#315f78;--shadow:0 18px 50px rgba(40,47,42,.08) }
    *{box-sizing:border-box} body{margin:0;color:var(--ink);background:radial-gradient(circle at 5% 0,rgba(59,119,83,.13),transparent 28rem),var(--paper);font-family:Inter,ui-sans-serif,system-ui,sans-serif} button,select,input{font:inherit}.shell{width:min(1480px,calc(100% - 32px));margin:auto}header{padding:44px 0 25px}.eyebrow{color:var(--green);font-size:.74rem;font-weight:850;letter-spacing:.14em;text-transform:uppercase}h1,h2{font-family:Georgia,serif;font-weight:500;letter-spacing:-.035em}h1{margin:8px 0;font-size:clamp(2.5rem,5vw,4.7rem);line-height:1}header p{max-width:760px;color:var(--muted);line-height:1.55}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:24px 0}.stat{padding:17px;border:1px solid var(--line);border-radius:14px;background:rgba(255,253,248,.8);box-shadow:var(--shadow)}.stat small{color:var(--muted)}.stat strong{display:block;margin-top:7px;font:500 1.8rem Georgia,serif}.controls{position:sticky;top:0;z-index:5;display:grid;grid-template-columns:1fr auto auto;gap:8px;padding:11px 0;background:rgba(243,239,230,.94);backdrop-filter:blur(10px)}input,select{min-height:43px;padding:0 12px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--ink)}.workspace{display:grid;grid-template-columns:380px minmax(0,1fr);gap:14px;align-items:start;padding-bottom:50px}.list,.detail{border:1px solid var(--line);border-radius:15px;background:var(--panel);box-shadow:var(--shadow)}.list{overflow:hidden}.list-head{display:flex;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--line);color:var(--muted);font-size:.8rem}#list{max-height:calc(100vh - 85px);overflow:auto}.item{display:block;width:100%;padding:14px;border:0;border-bottom:1px solid #ece7dd;background:transparent;text-align:left;color:inherit;cursor:pointer}.item:hover,.item.active{background:#edf3ee}.item.active{box-shadow:inset 3px 0 var(--green)}.item-top{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:.72rem;font-weight:800;text-transform:uppercase}.preview{display:-webkit-box;overflow:hidden;margin-top:7px;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-height:1.35}.chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}.chip{padding:4px 7px;border-radius:99px;background:#e8e6df;font-size:.68rem;font-weight:750}.chip.bad{color:var(--red);background:var(--red2)}.chip.good{color:var(--green);background:var(--green2)}.detail{padding:clamp(20px,3vw,34px);min-height:70vh}.detail h2{margin:8px 0 18px;font-size:clamp(1.45rem,3vw,2.25rem);line-height:1.2}.responses,.judges{display:grid;grid-template-columns:1fr 1fr;gap:10px}.card{border:1px solid var(--line);border-radius:12px;overflow:hidden}.card-head{display:flex;justify-content:space-between;gap:8px;padding:12px 14px;border-bottom:1px solid var(--line);background:#faf8f1;font-size:.82rem}.body{max-height:460px;overflow:auto;padding:17px;white-space:pre-wrap;line-height:1.52;font-size:.86rem}.section-title{margin:27px 0 10px;font-size:.76rem;font-weight:850;letter-spacing:.11em;text-transform:uppercase}.judge{padding:16px;border:1px solid var(--line);border-radius:12px}.judge h3{margin:0;font-size:1rem}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:12px 0}.metric{padding:8px;border-radius:8px;background:#f0eee7;font-size:.72rem}.metric b{display:block;margin-top:3px;font-size:.85rem}.reason{margin-top:11px;padding-top:10px;border-top:1px solid var(--line);font-size:.82rem;line-height:1.45}.reason b{color:var(--blue)}.empty{padding:50px 20px;color:var(--muted);text-align:center}@media(max-width:900px){.stats{grid-template-columns:1fr 1fr}.workspace{grid-template-columns:1fr}#list{max-height:390px}}@media(max-width:650px){.controls,.responses,.judges{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.shell{width:calc(100% - 20px)}}
  </style>
</head>
<body><header class="shell"><div class="eyebrow">HERON · Full 30-scenario experiment</div><h1>Pairwise judge review</h1><p>Inspect scalar-derived preferences, direct pairwise reasoning, and every response-order change. Cases with the most consistency problems appear first.</p><div class="stats" id="stats"></div></header>
<main class="shell"><div class="controls"><input id="search" type="search" placeholder="Search scenarios…"><select id="track"><option value="all">Both tracks</option><option value="gemini">Gemini judges</option><option value="openai">OpenAI judges</option></select><select id="issue"><option value="all">All cases</option><option value="position">Position changes</option><option value="disagreement">Judge disagreements</option><option value="scalar">Scalar/pairwise mismatches</option></select></div><div class="workspace"><aside class="list"><div class="list-head"><span>Cases</span><span id="count"></span></div><div id="list"></div></aside><article class="detail" id="detail"><div class="empty">Select a scenario.</div></article></div></main>
<script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),state={selected:null,rows:[]};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[c]);
const pct=v=>`${Number(v).toFixed(1)}%`;
function issueInfo(row){const judges=Object.keys(row.pairwise),first=judges[0],second=judges[1],position=judges.some(j=>row.pairwise[j].forward.normalized_preference!==row.pairwise[j].reverse.normalized_preference),disagreement=['forward','reverse'].some(o=>row.pairwise[first][o].normalized_preference!==row.pairwise[second][o].normalized_preference),scalar=judges.some(j=>{const f=row.pairwise[j].forward.normalized_preference,r=row.pairwise[j].reverse.normalized_preference;return f===r&&f!==row.scalar[j].scalar_preference});return{position,disagreement,scalar,score:Number(position)+Number(disagreement)+Number(scalar)}}
function renderStats(){const g=data.analysis.tracks.gemini,o=data.analysis.tracks.openai;$('stats').innerHTML=`<div class="stat"><small>Valid pairwise calls</small><strong>${data.analysis.pairwise_call_count}</strong></div><div class="stat"><small>Gemini scalar → pairwise</small><strong>${pct(g.scalar_interjudge_agreement.percentage)} → ${pct(g.pairwise_interjudge_agreement.all_orders.percentage)}</strong></div><div class="stat"><small>OpenAI scalar → pairwise</small><strong>${pct(o.scalar_interjudge_agreement.percentage)} → ${pct(o.pairwise_interjudge_agreement.all_orders.percentage)}</strong></div><div class="stat"><small>Anthropic calls</small><strong>${data.analysis.anthropic_call_count}</strong></div>`}
function filter(){const q=$('search').value.toLowerCase(),track=$('track').value,issue=$('issue').value;state.rows=data.comparisons.filter(r=>(track==='all'||r.track===track)&&(!q||`${r.question} ${r.response_1} ${r.response_2}`.toLowerCase().includes(q))&&(issue==='all'||issueInfo(r)[issue])).sort((a,b)=>issueInfo(b).score-issueInfo(a).score||Number(a.question_id)-Number(b.question_id));if(!state.rows.some(r=>r.pair_key===state.selected))state.selected=state.rows[0]?.pair_key||null;renderList();renderDetail()}
function renderList(){$('count').textContent=`${state.rows.length} shown`;$('list').innerHTML=state.rows.length?state.rows.map(r=>{const i=issueInfo(r);return`<button class="item ${r.pair_key===state.selected?'active':''}" data-key="${esc(r.pair_key)}"><div class="item-top"><span>Q${r.question_id} · ${r.track}</span><span>${i.score} issues</span></div><div class="preview">${esc(r.question)}</div><div class="chips">${i.position?'<span class="chip bad">order change</span>':'<span class="chip good">order stable</span>'}${i.disagreement?'<span class="chip bad">judge disagreement</span>':''}${i.scalar?'<span class="chip">scalar mismatch</span>':''}</div></button>`}).join(''):'<div class="empty">No matching cases.</div>';document.querySelectorAll('.item').forEach(b=>b.onclick=()=>{state.selected=b.dataset.key;renderList();renderDetail()})}
function renderDetail(){const r=data.comparisons.find(x=>x.pair_key===state.selected);if(!r){$('detail').innerHTML='<div class="empty">No scenario selected.</div>';return}const judges=Object.keys(r.pairwise);const judgeCards=judges.map(j=>{const s=r.scalar[j],f=r.pairwise[j].forward,v=r.pairwise[j].reverse,stable=f.normalized_preference===v.normalized_preference;return`<section class="judge"><h3>${esc(f.judge_label)}</h3><div class="chips"><span class="chip ${stable?'good':'bad'}">${stable?'order stable':'order changed'}</span></div><div class="metric-grid"><div class="metric">Scalar preference<b>${esc(s.scalar_preference)}</b></div><div class="metric">Forward pairwise<b>${esc(f.normalized_preference)}</b></div><div class="metric">Reverse pairwise<b>${esc(v.normalized_preference)}</b></div></div><div class="reason"><b>Forward reasoning</b><br>${esc(f.reasoning)}</div><div class="reason"><b>Reverse reasoning</b><br>${esc(v.reasoning)}</div></section>`}).join('');$('detail').innerHTML=`<div class="eyebrow">Question ${r.question_id} · ${r.track} judges</div><h2>${esc(r.question)}</h2><div class="responses"><section class="card"><div class="card-head"><strong>${esc(r.response_1_label)}</strong><span>Response 1</span></div><div class="body">${esc(r.response_1)}</div></section><section class="card"><div class="card-head"><strong>${esc(r.response_2_label)}</strong><span>Response 2</span></div><div class="body">${esc(r.response_2)}</div></section></div><div class="section-title">Judge comparison</div><div class="judges">${judgeCards}</div>`}
['search','track','issue'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',filter));renderStats();filter();
</script></body></html>'''


if __name__ == "__main__":
    main()
